do $$ begin
 if not exists (select 1 from pg_roles where rolname='anon') then create role anon; end if;
 if not exists (select 1 from pg_roles where rolname='authenticated') then create role authenticated; end if;
 if not exists (select 1 from pg_roles where rolname='service_role') then create role service_role; end if;
 if not exists (select 1 from pg_roles where rolname='supabase_admin') then create role supabase_admin; end if;
end $$;
create schema auth;
create function auth.uid() returns uuid language sql as $$ select nullif(current_setting('test.uid', true),'')::uuid $$;
create function auth.jwt() returns jsonb language sql as $$ select coalesce(nullif(current_setting('test.jwt', true),''),'{}')::jsonb $$;
create table public.pedidos (
 id bigint generated by default as identity primary key,
 telefone text, status text not null default 'pendente', itens jsonb not null default '[{"quantidade":1}]',
 cliente text default 'Teste', total numeric default 50
);
create table public.pagamentos_pix (
 id uuid primary key, pedido jsonb not null, pedido_id bigint, checkout_url text,
 valor_centavos integer, transaction_nsu text
);
create function public.confirmar_pagamento_pix(p_id uuid,p_transaction_nsu text,p_capture_method text,p_receipt_url text)
returns bigint language plpgsql security definer as $$
declare p public.pagamentos_pix; resultado bigint;
begin
 select * into p from public.pagamentos_pix where id = p_id for update;
 if p.pedido_id is not null then return p.pedido_id; end if;
 -- Simula a confirmação antiga que não copia a nova coluna cupom_codigo.
 insert into public.pedidos(telefone,itens) values(p.pedido->>'telefone',p.pedido->'itens') returning id into resultado;
 update public.pagamentos_pix set pedido_id = resultado, transaction_nsu = p_transaction_nsu where id = p_id;
 return resultado;
end $$;
grant usage on schema public to anon,authenticated,service_role;
grant select,insert,update,delete on public.pedidos to anon,authenticated,service_role;
grant usage,select on sequence public.pedidos_id_seq to anon,authenticated,service_role;
grant insert,select,update on public.pagamentos_pix to service_role;
